  "ruling": {
    "ruling": "FULL_REFUND",
    "amount_sgd": 4.5,
    "driver_compensation_sgd": null,
    "referrals": [
      "POL-NS-01: driver-education item — trip TRP-02724 was terminated under cancellation_reason_code DRIVER_UNABLE_TO_LOCATE although the driver had arrived at the pickup pin and served the free waiting period; the mis-selected reason code is recorded for driver review."
